begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create temporary table tap_results(line text);grant all on tap_results to authenticated;
create function pg_temp.i(n integer) returns uuid language sql immutable as $$select ('94000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.login(n integer) returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.i(n),'session_id',pg_temp.i(n),'role','authenticated','is_anonymous',false)::text,true)$$;
create function pg_temp.ctx() returns jsonb language sql as $$select jsonb_build_object('organizationId',pg_temp.i(1),'branchId',pg_temp.i(101),'productId',pg_temp.i(301))$$;
create function pg_temp.edit() returns jsonb language sql as $$select pg_temp.ctx()||jsonb_build_object('requestId',pg_temp.i(701),'expectedName','TEST Feed','expectedSku','FEED-1','expectedCategory','Feeds','expectedMinimumStock','0','name','TEST Feed renamed','sku','FEED-NEW','category','Feeds','minimumStock','2','reason','TEST checked label','confirmed',true)$$;
create function pg_temp.hide(n integer default 702) returns jsonb language sql as $$select pg_temp.ctx()||jsonb_build_object('requestId',pg_temp.i(n),'expectedName','TEST Feed renamed','expectedSku','FEED-NEW','typedSku','FEED-NEW','reason','TEST discontinued product','confirmed',true)$$;
create function pg_temp.restore(n integer default 703) returns jsonb language sql as $$select pg_temp.hide(n)||jsonb_build_object('hiddenRequestId',pg_temp.i(702),'reason','TEST owner restocking')$$;

set local role authenticated;select pg_temp.login(12);
select pg_temp.login(13);
select pg_temp.login(11);
reset role;
set local role authenticated;select pg_temp.login(11);
reset role;
set local role authenticated;select pg_temp.login(11);
reset role;update app_private.blind_counts set state='cancelled';
update public.products set source_stock='{"pending":true}' where id=pg_temp.i(301);
set local role authenticated;select pg_temp.login(11);
reset role;update public.products set source_stock=null where id=pg_temp.i(301);
set local role authenticated;select pg_temp.login(11);
reset role;
-- Exercise a complete server page and cursor without exposing source-retired records.
 select pg_temp.i(n),pg_temp.i(1),'TEST hidden page '||n,'PAGE-'||n,'piece',false from generate_series(1001,1051)n;
 select pg_temp.i(1),pg_temp.i(n),pg_temp.i(n+1000),'TEST pagination' from generate_series(1001,1051)n;
set local role authenticated;select pg_temp.login(11);
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.i(11),'session_id',pg_temp.i(11),'role','authenticated','is_anonymous',true)::text,true);
reset role;
delete from auth.sessions where id=pg_temp.i(11);
set local role authenticated;select pg_temp.login(11);
reset role;
select line from tap_results;
select * from finish();
rollback;
